using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Globalization;using System.Xml.Linq;
namespace V15Voice {
public sealed class CreatorStage {
 public AnchorStage Source;public double TrialNatural,TrialMeasured,TrialSpeed,TrialTail,TrialAdjustment;public bool TrialSuccess;public string RenderedText="",TrialInfo="";public string Accepted="",Draft="",Key="",Audio="",AudioHash="",PreviousAudio="",TrialAudio="",TrialHash="",TrialKey="",Reason="";public bool Success,Reviewed,Pending;public double Natural,Measured,Speed,Tail,Adjustment;
 public string Text{get{return Accepted.Length>0?Accepted:Source.Text;}}
 public bool NeedsReview{get{return Tail>=.6||Source.FallbackBoundary;}}
 public string Status{get{return Key.Length==0?"Chưa đo":!Success?"Cần sửa: "+Reason:NeedsReview&&!Reviewed?"Cần nghe lại":Reviewed?"Đã duyệt":"Đạt";}}
 public AnchorStage Effective(string text){return new AnchorStage{Number=Source.Number,FallbackBoundary=Source.FallbackBoundary,Cues=new List<Cue>{new Cue{Id=Source.Cues.First().Id,Start=Source.Start,End=Source.End,Text=text}}};}
}
public sealed class CreatorProject {
 public string SourcePath,Stamp,Folder,Video="",Settings="",Signature="",Voice="",Output="",Report="",AttemptError="";public List<Cue> Sources;public List<CreatorStage> Stages=new List<CreatorStage>();
 public static string Hash(string s){return SpeechArchive.Hash(s??"");}
 public string FilePath{get{return Path.Combine(Folder,"project.xml");}}
 public static CreatorProject Open(string source,List<Cue> cues,string state){
  var p=new CreatorProject{SourcePath=Path.GetFullPath(source),Sources=VoiceRenderReport.Snapshot(cues),Folder=Path.Combine(state,"creator",Hash(Path.GetFullPath(source).ToLowerInvariant()))};
  p.Stamp=Hash(StateFiles.Hash(source)+"|"+Scripts.ToSrt(cues)+"|"+String.Join(",",cues.Select(c=>c.AnchorAfter)));p.Stages=AnchoredVoice.Plan(p.Sources).Select(s=>new CreatorStage{Source=s}).ToList();
  var x=StateFiles.Read(p.FilePath);if(x==null)return p;p.Video=StateFiles.S(x,"video");if(StateFiles.S(x,"stamp")!=p.Stamp)return p;
  p.Settings=StateFiles.S(x,"settings");p.Signature=StateFiles.S(x,"signature");p.Voice=StateFiles.S(x,"voice");p.Output=StateFiles.S(x,"output");p.Report=StateFiles.S(x,"report");p.AttemptError=StateFiles.S(x,"attemptError");
  foreach(var a in x.Elements("stage")){int i=StateFiles.I(a,"n")-1;if(i<0||i>=p.Stages.Count)continue;var s=p.Stages[i];s.RenderedText=StateFiles.S(a,"renderedText");s.TrialInfo=StateFiles.S(a,"trialInfo");s.TrialNatural=StateFiles.D(a,"trialNatural");s.TrialMeasured=StateFiles.D(a,"trialMeasured");s.TrialSpeed=StateFiles.D(a,"trialSpeed");s.TrialTail=StateFiles.D(a,"trialTail");s.TrialAdjustment=StateFiles.D(a,"trialAdjustment");s.Adjustment=StateFiles.D(a,"adjustment");s.TrialSuccess=StateFiles.I(a,"trialSuccess")==1;s.Accepted=StateFiles.S(a,"accepted");s.Draft=StateFiles.S(a,"draft");s.Key=StateFiles.S(a,"key");s.Audio=Local(p,StateFiles.S(a,"audio"));s.AudioHash=StateFiles.S(a,"hash");s.PreviousAudio=Local(p,StateFiles.S(a,"previous"));s.TrialAudio=Local(p,StateFiles.S(a,"trial"));s.TrialHash=StateFiles.S(a,"trialHash");s.TrialKey=StateFiles.S(a,"trialKey");s.Success=StateFiles.I(a,"success")==1;s.Reviewed=StateFiles.I(a,"reviewed")==1;s.Pending=StateFiles.I(a,"pending")==1;s.Natural=StateFiles.D(a,"natural");s.Measured=StateFiles.D(a,"measured");s.Speed=StateFiles.D(a,"speed");s.Tail=StateFiles.D(a,"tail");s.Reason=StateFiles.S(a,"reason");}
  return p;
 }
 static string Local(CreatorProject p,string name){return name.Length>0&&name==Path.GetFileName(name)?Path.Combine(p.Folder,name):"";}
 static string Name(string p){return String.IsNullOrEmpty(p)?"":Path.GetFileName(p);}
 public void Save(){var x=new XElement("creator",new XAttribute("schema",1),new XAttribute("source",SourcePath),new XAttribute("stamp",Stamp),new XAttribute("video",Video),new XAttribute("settings",Settings),new XAttribute("signature",Signature),new XAttribute("voice",Voice),new XAttribute("output",Output),new XAttribute("report",Report),new XAttribute("attemptError",AttemptError));foreach(var s in Stages)x.Add(new XElement("stage",new XAttribute("n",s.Source.Number),new XAttribute("renderedText",s.RenderedText),new XAttribute("trialInfo",s.TrialInfo),new XAttribute("trialNatural",s.TrialNatural),new XAttribute("trialMeasured",s.TrialMeasured),new XAttribute("trialSpeed",s.TrialSpeed),new XAttribute("trialTail",s.TrialTail),new XAttribute("trialAdjustment",s.TrialAdjustment),new XAttribute("adjustment",s.Adjustment),new XAttribute("trialSuccess",s.TrialSuccess?1:0),new XAttribute("accepted",s.Accepted),new XAttribute("draft",s.Draft),new XAttribute("key",s.Key),new XAttribute("audio",Name(s.Audio)),new XAttribute("hash",s.AudioHash),new XAttribute("previous",Name(s.PreviousAudio)),new XAttribute("trial",Name(s.TrialAudio)),new XAttribute("trialHash",s.TrialHash),new XAttribute("trialKey",s.TrialKey),new XAttribute("success",s.Success?1:0),new XAttribute("reviewed",s.Reviewed?1:0),new XAttribute("pending",s.Pending?1:0),new XAttribute("natural",s.Natural),new XAttribute("measured",s.Measured),new XAttribute("speed",s.Speed),new XAttribute("tail",s.Tail),new XAttribute("reason",s.Reason)));StateFiles.Write(FilePath,x);}
 public static string Pair(string source,IEnumerable<string> videos){var all=videos.Where(File.Exists).Select(Path.GetFullPath).Distinct(StringComparer.OrdinalIgnoreCase).Where(v=>String.Equals(Path.GetFileNameWithoutExtension(v),Path.GetFileNameWithoutExtension(source),StringComparison.OrdinalIgnoreCase)).ToList();var same=all.Where(v=>String.Equals(Path.GetDirectoryName(v),Path.GetDirectoryName(Path.GetFullPath(source)),StringComparison.OrdinalIgnoreCase)).ToList();return same.Count==1?same[0]:same.Count==0&&all.Count==1?all[0]:"";}
 public void Accept(CreatorStage s){if(String.IsNullOrWhiteSpace(s.Draft))throw new Exception("Nhập lời bản sửa trước.");if(s.Draft.Length>20000)throw new Exception("Một chặng tối đa 20.000 ký tự.");if(s.Text==s.Draft.Trim()&&!(s.TrialNatural>0&&File.Exists(s.TrialAudio)&&s.TrialKey==CreatorRenderer.Key(this,s,Signature,s.Draft.Trim())))return;s.PreviousAudio=s.Audio;s.Accepted=s.Draft.Trim();s.Pending=true;s.Reviewed=false;Output="";Save();}
 public void ValidateSource(){if(!File.Exists(SourcePath))throw new FileNotFoundException("Không thấy SRT nguồn.",SourcePath);string stamp=Hash(StateFiles.Hash(SourcePath)+"|"+Scripts.ToSrt(Sources)+"|"+String.Join(",",Sources.Select(c=>c.AnchorAfter)));if(stamp!=Stamp)throw new Exception("SRT nguồn đã thay đổi; nhập lại để tránh áp dụng bản sửa vào mốc cũ.");}
}
public static class CreatorRenderer {
 static string F(double n){return n.ToString("0.000",CultureInfo.InvariantCulture);}
 public static string Signature(KokoroEngine e,RenderOptions o){return CreatorProject.Hash(String.Join("|",new[]{"creator206-v1",SpeechArchive.Key(e,"creator-profile",o.BaseSpeed),e.Kind.ToString(),e.ModelFolder,e.Speaker.ToString(),e.VoiceName??"",e.ReferenceText??"",File.Exists(e.ReferencePath)?StateFiles.Hash(e.ReferencePath):"",F(o.BaseSpeed),F(o.MinSpeed),F(o.MaxSpeed),o.GentleFit.ToString(),o.Punctuation.ToString(),F(o.CommaPause),F(o.StopPause),F(o.QuestionPause),F(o.ParagraphPause),F(o.Gap),o.Breathing.ToString(),F(o.BreathLevel),o.BreathEvery.ToString(),File.Exists(o.BreathPath)?StateFiles.Hash(o.BreathPath):"",o.NormalizeLoudness.ToString(),F(o.TargetLufs),e.DeviceMode??""}));}
 public static string Key(CreatorProject p,CreatorStage s,string signature,string text){return CreatorProject.Hash(p.Stamp+"|"+signature+"|"+s.Source.Number+"|"+text);}
 static bool Valid(string file,string hash){try{return File.Exists(file)&&StateFiles.Hash(file)==hash&&FinalAudio.PcmFrames(file)>0;}catch{return false;}}
 static AnchorFit Read(CreatorProject p,CreatorStage s,KokoroEngine e,RenderOptions o,string text,string key,Action<AnchorFit,string> complete){
  string work=Path.Combine(p.Folder,"work-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);try{var stage=s.Effective(text);if(o.RunReport!=null){o.RunReport.BeginStage(stage);o.RunReport.CurrentStage.Text=text;}var units=new List<AnchorUnit>();var natural=AnchoredVoice.ReadStage(stage,e,o,new BreathTrack(o,e.Root),work,units);if(o.RunReport!=null){o.RunReport.StageNatural(natural.Duration);o.RunReport.Step("FIT","Căn chặng để duyệt video");}var fit=AnchoredVoice.Fit(natural,stage.Budget,o,e.Root,work,()=>e.Cancelled);
   double pause=Math.Max(0,stage.Budget-fit.Audio.Duration);if(!fit.Success&&pause>0&&pause<=1.5){var exact=new short[(int)Math.Round(stage.Budget*24000)];Array.Copy(fit.Audio.Samples,exact,fit.Audio.Samples.Length);fit.Audio=new Wave{Rate=24000,Samples=exact};fit.Success=true;fit.Reason="Giữ nghỉ cuối "+F(pause)+"s để giữ mốc; cần nghe duyệt.";}
   if(o.RunReport!=null)o.RunReport.StageDone(stage,fit);if(e.Cancelled)throw new OperationCanceledException();string audio=Path.Combine(p.Folder,key+"-"+Guid.NewGuid().ToString("N")+".wav");fit.Audio.Write(Path.Combine(work,"ready.wav"));if(File.Exists(audio))File.Delete(audio);File.Move(Path.Combine(work,"ready.wav"),audio);complete(fit,audio);return fit;
  }finally{try{Directory.Delete(work,true);}catch{}}}
 public static void Trial(CreatorProject p,CreatorStage s,KokoroEngine e,RenderOptions o,string text){o.Anchored=true;var prior=e.RunReport;var report=new VoiceRenderReport(p.Sources,e,o,OutputFiles.Beside(p.SourcePath));o.RunReport=report;e.RunReport=report;p.Report=report.PathName;try{p.ValidateSource();if(String.IsNullOrWhiteSpace(text)||text.Length>20000)throw new Exception("Lời bản sửa cần từ 1 đến 20.000 ký tự.");report.Step("MODEL","Kiểm tra model/runtime giọng");e.CheckFiles();Tempo.Validate(o);Punctuation.Validate(o);string signature=Signature(e,o);if(p.Signature.Length==0||s.Key.Length==0)throw new Exception("Chạy tạo và kiểm tra hàng đợi trước khi đo thử bản sửa.");if(p.Signature!=signature)throw new Exception("Thiết lập giọng đã khác lần đo. Nạp thiết lập lần đo hoặc chạy toàn bộ trước khi so sánh.");string key=Key(p,s,signature,text.Trim());bool fitSuccess=false;string fitReason="";Read(p,s,e,o,text.Trim(),key,(fit,audio)=>{fitSuccess=fit.Success;fitReason=fit.Reason;s.TrialNatural=fit.Natural;s.TrialMeasured=fit.Measured;s.TrialSpeed=fit.Speed;s.TrialSuccess=fit.Success;s.TrialAdjustment=fit.SampleAdjustment;s.TrialTail=Punctuation.EdgeSilence(fit.Audio,false)+Math.Max(0,(s.Source.Number<p.Stages.Count?p.Stages[s.Source.Number].Source.Start:s.Source.End)-s.Source.End);s.TrialKey=key;s.TrialAudio=audio;s.TrialHash=StateFiles.Hash(audio);s.Draft=text.Trim();s.TrialInfo="Gốc "+F(fit.Natural)+"s; sau căn "+F(fit.Measured)+"s; "+F(fit.Speed)+"x; "+(fit.Success?"Vừa khung":"Chưa đạt: "+fit.Reason)+(fit.Success&&fit.Reason.Length>0?" · "+fit.Reason:"");});report.Finish(fitSuccess?"ĐO THỬ · CHƯA XUẤT WAV TỔNG":"ĐO THỬ · CHƯA KHỚP KHUNG","",fitSuccess?null:new Exception("Chặng thử không khớp timeline: "+fitReason));}catch(Exception ex){report.Finish(ex is OperationCanceledException?"ĐÃ DỪNG":"THẤT BẠI","",ex);throw;}finally{e.RunReport=prior;p.Save();}}
 public static string Run(CreatorProject p,KokoroEngine e,RenderOptions o,bool repairsOnly,Action<int,string> notify){
  o.Anchored=true;o.TargetSeconds=0;var prior=e.RunReport;var report=new VoiceRenderReport(p.Sources,e,o,OutputFiles.Beside(p.SourcePath));o.RunReport=report;e.RunReport=report;p.Report=report.PathName;string temp=Path.Combine(p.Folder,"assembled-"+Guid.NewGuid().ToString("N")+".wav");int regenerated=0,reused=0;p.Output="";p.AttemptError="";try{
   report.Step("INPUT","Kiểm tra nguồn và thiết lập duyệt");p.ValidateSource();Tempo.Validate(o);Punctuation.Validate(o);FinalAudio.Validate(o);string sig=Signature(e,o);if(repairsOnly&&p.Signature!=sig)throw new Exception("Thiết lập giọng / giới hạn đã đổi. Nạp thiết lập lần đo hoặc chạy toàn bộ để đo lại đúng giọng.");if(p.Signature!=sig){foreach(var old in p.Stages){old.PreviousAudio=old.Audio;old.Key=old.Audio="";old.Natural=old.Measured=old.Speed=old.Tail=0;old.Success=old.Reviewed=false;}p.Signature=sig;}report.Step("MODEL","Kiểm tra model/runtime giọng");e.CheckFiles();Directory.CreateDirectory(p.Folder);p.Output="";
   foreach(var s in p.Stages){if(e.Cancelled)throw new OperationCanceledException();string key=Key(p,s,sig,s.Text);notify((s.Source.Number-1)*85/p.Stages.Count,"Chặng "+s.Source.Number+"/"+p.Stages.Count);e.RenderContext=Path.GetFileName(p.SourcePath)+" · chặng "+s.Source.Number;try{
    if(s.Pending&&s.TrialKey==key&&s.TrialNatural>0&&Valid(s.TrialAudio,s.TrialHash)){s.PreviousAudio=s.Audio;s.Audio=s.TrialAudio;s.AudioHash=s.TrialHash;s.Key=key;s.Natural=s.TrialNatural;s.Measured=s.TrialMeasured;s.Speed=s.TrialSpeed;s.Success=s.TrialSuccess;s.Tail=s.TrialTail;s.Adjustment=s.TrialAdjustment;s.RenderedText=s.Text;s.Reason=s.TrialSuccess?"Đã dùng đúng bản B đã nghe thử. "+s.TrialInfo:s.TrialInfo;s.Reviewed=false;var stage=s.Effective(s.Text);report.BeginStage(stage);report.CurrentStage.Text=s.Text;report.StageNatural(s.Natural);report.StageDone(stage,new AnchorFit{Natural=s.Natural,Measured=s.Measured,Speed=s.Speed,Success=s.Success,Reason=s.Reason,SampleAdjustment=s.Adjustment,Audio=Wave.Read(s.Audio)});regenerated++;}
    else if(s.Key==key&&Valid(s.Audio,s.AudioHash)){reused++;var stage=s.Effective(s.Text);report.BeginStage(stage);report.CurrentStage.Text=s.Text;report.StageNatural(s.Natural);report.StageDone(stage,new AnchorFit{Natural=s.Natural,Measured=s.Measured,Speed=s.Speed,Success=s.Success,Reason=s.Reason,SampleAdjustment=s.Adjustment,Audio=new Wave{Rate=24000,Samples=new short[(int)FinalAudio.PcmFrames(s.Audio)]}});}
    else{bool changed=s.Key.Length>0;if(changed)s.PreviousAudio=s.Audio;s.Reviewed=false;Read(p,s,e,o,s.Text,key,(fit,audio)=>{s.RenderedText=s.Text;s.Key=key;s.Audio=audio;s.AudioHash=StateFiles.Hash(audio);s.Natural=fit.Natural;s.Measured=fit.Measured;s.Speed=fit.Speed;s.Success=fit.Success;s.Reason=fit.Reason;s.Adjustment=fit.SampleAdjustment;s.Tail=Punctuation.EdgeSilence(fit.Audio,false)+Math.Max(0,(s.Source.Number<p.Stages.Count?p.Stages[s.Source.Number].Source.Start:s.Source.End)-s.Source.End);});regenerated++;}s.Pending=!s.Success&&s.Accepted.Length>0;
   }catch(OperationCanceledException){throw;}catch(Exception ex){s.Success=false;s.Key=key;s.Audio="";s.Reason=ex.Message;s.Reviewed=false;report.ProcessFailure("Tạo chặng",null,"",ex,false);if(report.Current!=null){report.Current.Status="Lỗi tại đơn vị này";report.Current.Error=ex.Message;report.Current=null;}if(report.CurrentStage!=null){report.CurrentStage.Status="Lỗi tại chặng";report.CurrentStage.Reason=ex.Message;report.CurrentStage=null;}}p.Signature=sig;p.Save();}
   if(p.Stages.Any(s=>!s.Success))throw new Exception("Chưa xuất WAV: "+p.Stages.Count(s=>!s.Success)+" chặng cần sửa; các audio đã đo được giữ để duyệt.");
   report.Step("ASSEMBLE","Ghép chặng đã đo; giữ audio các chặng không sửa");using(var writer=new StreamingWave(temp,24000)){foreach(var s in p.Stages){if(e.Cancelled)throw new OperationCanceledException();writer.At(s.Source.Start,Wave.Read(s.Audio));}writer.Finish(p.Sources.Last().End);}
   long frames=(long)Math.Round(p.Sources.Last().End*24000);if(FinalAudio.PcmFrames(temp)!=frames)throw new IOException("WAV không khớp tổng mốc nguồn.");if(o.NormalizeLoudness){report.Step("NORMALIZE","Cân âm WAV tổng; có thể thay đổi mức âm của các chặng");FinalAudio.Normalize(e.Root,temp,temp+".norm.wav",frames,o.TargetLufs,()=>e.Cancelled,e.ReportActivity);File.Copy(temp+".norm.wav",temp,true);}if(e.Cancelled)throw new OperationCanceledException();p.ValidateSource();report.Step("PUBLISH","Xuất WAV cạnh SRT; giữ các bản cũ");p.Output=OutputFiles.Publish(temp,OutputFiles.Beside(p.SourcePath));report.Finish("THÀNH CÔNG",p.Output,null);notify(100,"Đã ghép WAV · "+regenerated+" chặng tạo lại · "+reused+" dùng lại");return p.Output;
  }catch(Exception ex){p.AttemptError=ex.Message;report.Finish(ex is OperationCanceledException?"ĐÃ DỪNG":"THẤT BẠI","",ex);throw;}
  finally{try{if(File.Exists(report.PathName)){var b=new StringBuilder("\r\nDUYỆT / SỬA CHẶNG · 2.0.6\r\nGiọng: "+p.Voice+"\r\nVideo: "+p.Video+"\r\nTạo lại: "+regenerated+"; dùng lại audio chặng: "+reused+"\r\nHơi thở tính riêng trong từng chặng. Cân âm tổng có thể thay đổi mức âm; mốc và audio chặng đệm vẫn giữ.\r\n");foreach(var s in p.Stages)b.Append("Chặng ").Append(s.Source.Number).Append(" ").Append(Scripts.Stamp(s.Source.Start)).Append(" → ").Append(Scripts.Stamp(s.Source.End)).Append("\r\nLời gốc: ").Append(s.Source.Text).Append("\r\nLời dùng: ").Append(s.Text).Append("\r\nGốc ").Append(s.Natural>0?F(s.Natural):"chưa đo").Append("s; sau căn trước nghỉ ").Append(s.Natural>0?F(s.Measured):"chưa đo").Append("s; tốc độ ").Append(F(s.Speed)).Append("x; nghỉ cuối ").Append(F(s.Tail)).Append("s; ").Append(s.Status).Append("\r\n");File.AppendAllText(report.PathName,b.ToString());}}catch{}p.Save();e.RunReport=prior;o.RunReport=report;e.RenderContext="";try{File.Delete(temp);File.Delete(temp+".norm.wav");}catch{}}
 }
}}
